int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct airspy_device *dev;
    int ret = -ENOMEM;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        goto error;

    mutex_init(&dev->lock);
    mutex_init(&dev->buf_lock);

    ret = airspy_identify_usb_device(dev, intf);
    if (ret < 0)
        goto error;

    dev->v4l2_dev.release = airspy_v4l2_release;
    dev->v4l2_dev.lock = airspy_v4l2_lock;
    dev->v4l2_dev.ctrl_handler = &dev->v4l2_ctrl_handler;
    dev->v4l2_dev.dev = &intf->dev;
    strscpy(dev->v4l2_dev.name, "Airspy", sizeof(dev->v4l2_dev.name));

    v4l2_ctrl_handler_init(&dev->v4l2_ctrl_handler, 16);
    ret = airspy_setup_controls(dev);
    if (ret < 0)
        goto error;

    v4l2_device_register(&intf->dev, &dev->v4l2_dev);
    airspy_vb2_queue_init(dev);

    usb_set_intfdata(intf, dev);

    dev_info(&intf->dev, "Airspy SDR device registered (Experimental API)");
    dev_notice(&intf->dev, "Airspy SDR API is experimental and may change");

    return 0;

error:
    if (dev) {
        if (dev->v4l2_dev.ctrl_handler)
            v4l2_ctrl_handler_free(&dev->v4l2_ctrl_handler);
        kfree(dev);
    }
    return ret;
}

int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
