int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct airspy_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    mutex_init(&dev->lock);
    spin_lock_init(&dev->slock);

    ret = airspy_usb_detect_device(dev, intf);
    if (ret < 0)
        goto err_free_dev;

    ret = vb2_queue_alloc(&dev->queue, V4L2_BUF_TYPE_VIDEO_CAPTURE, 4);
    if (ret < 0)
        goto err_free_dev;

    dev->vdev = video_device_alloc();
    if (!dev->vdev) {
        ret = -ENOMEM;
        goto err_free_queue;
    }

    strlcpy(dev->vdev->name, "airspy", sizeof(dev->vdev->name));
    dev->vdev->fops = &airspy_fops;
    dev->vdev->ioctl_ops = &airspy_ioctl_ops;
    dev->vdev->release = video_device_release;
    dev->vdev->vfl_dir = VFL_DIR_RX;
    dev->vdev->minor = -1;
    dev->vdev->v4l2_dev = &dev->v4l2_dev;

    ret = v4l2_device_register(&intf->dev, &dev->v4l2_dev);
    if (ret < 0)
        goto err_free_vdev;

    ret = video_register_device(dev->vdev, VFL_TYPE_VIDEO, -1);
    if (ret < 0)
        goto err_unregister_v4l2;

    dev->intf = intf;
    dev->udev = usb_get_dev(usb_ifnum_to_dev(intf, intf->altsetting[0].desc.bInterfaceNumber));

    v4l2_ctrl_handler_init(&dev->ctrl_handler, 10);
    ret = airspy_setup_gains(dev);
    if (ret < 0)
        goto err_cleanup_ctrl;

    dev->vdev->ctrl_handler = &dev->ctrl_handler;

    usb_set_intfdata(intf, dev);

    dev_info(&intf->dev, "Airspy device initialized. This is an experimental SDR API.\n");

    return 0;

err_cleanup_ctrl:
    v4l2_ctrl_handler_free(&dev->ctrl_handler);
err_unregister_v4l2:
    v4l2_device_unregister(&dev->v4l2_dev);
err_free_vdev:
    video_device_release(dev->vdev);
err_free_queue:
    vb2_queue_free(&dev->queue);
err_free_dev:
    kfree(dev);
    return ret;
}

int airspy_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct airspy_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    mutex_init(&dev->lock);
    spin_lock_init(&dev->slock);

    ret = airspy_detect(dev);
    if (ret < 0)
        goto error_free_dev;

    ret = videobuf2_queue_init(&dev->vb2_q, &airspy_queue_ops, &intf->dev,
                               V4L2_BUF_FLAG_VIDEO_OUTPUT, V4L2_MEMORY_MMAP);
    if (ret < 0)
        goto error_free_dev;

    strlcpy(dev->vdev.name, "Airspy", sizeof(dev->vdev.name));
    dev->vdev.vfl_dir = VFL_DIR_M2M;
    dev->vdev.release = video_device_release_empty;
    dev->vdev.queue = &dev->vb2_q;
    dev->vdev.lock = &dev->lock;
    dev->vdev.device_caps = V4L2_CAP_VIDEO_CAPTURE | V4L2_CAP_READWRITE;

    ret = video_register_device(&dev->vdev, VFL_TYPE_VIDEO, -1);
    if (ret < 0)
        goto error_cleanup_vb2;

    ret = v4l2_device_register(&intf->dev, &dev->v4l2_dev);
    if (ret < 0)
        goto error_unregister_video;

    ret = airspy_setup_controls(dev);
    if (ret < 0)
        goto error_unregister_v4l2;

    usb_set_intfdata(intf, dev);
    dev_info(&intf->dev, "Airspy device initialized: %s", id->driver_info);

    return 0;

error_unregister_v4l2:
    v4l2_device_unregister(&dev->v4l2_dev);
error_unregister_video:
    video_unregister_device(&dev->vdev);
error_cleanup_vb2:
    videobuf2_queue_release(&dev->vb2_q);
error_free_dev:
    kfree(dev);
    return ret;
}

int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct airspy_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    mutex_init(&dev->lock);
    spin_lock_init(&dev->irq_lock);

    ret = airspy_init_device(dev, intf);
    if (ret < 0)
        goto error_free_dev;

    ret = videobuf2_queue_alloc(&dev->vb2_queue, &airspy_queue_ops, &dev->pdev->dev, V4L2_MEMORY_MMAP, NULL);
    if (ret < 0)
        goto error_cleanup_device;

    ret = airspy_setup_video_device(dev);
    if (ret < 0)
        goto error_free_vb2_queue;

    ret = v4l2_device_register(&dev->pdev->dev, &dev->v4l2_dev);
    if (ret < 0)
        goto error_cleanup_video_device;

    ret = airspy_register_controls(dev);
    if (ret < 0)
        goto error_unregister_v4l2_device;

    dev_info(&dev->pdev->dev, "Airspy device registered.");
    dev_info(&dev->pdev->dev, "SDR API is experimental and subject to change.");

    return 0;

error_unregister_v4l2_device:
    v4l2_device_unregister(&dev->v4l2_dev);
error_cleanup_video_device:
    airspy_cleanup_video_device(dev);
error_free_vb2_queue:
    videobuf2_queue_free(&dev->vb2_queue);
error_cleanup_device:
    airspy_cleanup_device(dev);
error_free_dev:
    kfree(dev);
    return ret;
}
